function CardProgressionEquipmentInfoNode:RefreshCardTip(dojo)
    local playerCardId = checkNumber(dojo.playerCardId)
    local isInstall = playerCardId > 0
    KTool.SetActive(self.CardTip.gameObject, isInstall)
    if isInstall then
        ---@type CardDojo
        local cardDojo = cardComp:GetCardById(playerCardId)
        local cardSkin = cardDojo.cardSkin
        ---@type CardSkinVo
        local skinVo = cardConfMgr:GetCardSkinBySkinId(cardSkin)
        CfUtils.FillImage(self.ImgRoleHead, skinVo.buffHead)
    end
end

function CardProgressionEquipmentInfoNode:RefreshEngrave(dojo)
    local isEngraved = checkInt(dojo.bindPlayerCardId) > 0
    if not isEngraved then
        CfUtils.SetActive(self.CultivateOverseaEquipEngraveHead, false)
        CfUtils.SetActive(self.Engrave, false)
        return
    end

    CfUtils.SetActive(self.CultivateOverseaEquipEngraveHead, true)
    CfUtils.SetActive(self.Engrave, true)
    local scr = CfUtils.GetLuaScr(self.CultivateOverseaEquipEngraveHead, CardProgressionConstants.EnvPath.EquipmentEngraveNode)
    if not scr then return end
    
    scr:RefreshNode(self._equipDojo)
    
    -- 更新刻印属性
    local isActive = EquipUtils.IsEngraveActive(dojo)
    CfUtils.SetActive(self.EngraveInvalid, not isActive)
    CfUtils.SetActive(self.EngraveEffective, isActive)
    if not isActive then
        local cardDojo = cardComp:GetCardById(dojo.bindPlayerCardId)    
        local cardVo =  cardConfMgr:GetCardByRefId(cardDojo.cardId)
        CfUtils.FillText(self.EngraveInvalidTxt, localize('（ 仅_name_穿戴生效）', {_name_ = cardVo.name}))
    end
    ---@type EquipVo
    local equipVo = cardConfMgr:GetEquipVoById(dojo.equipmentId)
    local mainAttrAdditionId = dojo.mainAttrId
    local attrAdditionVo = cardConfMgr:GetBasicAttrAdditionById(mainAttrAdditionId)
    local mainEquipAttrVo = cardConfMgr:GetEquipAttrVoById(equipVo.poolMain)
    local attrAddVo = cardConfMgr:GetBasicAttrAdditionById(mainEquipAttrVo.attrAdditionId)
    local attrVo = cardConfMgr:GetBasicAttr(attrAddVo.attrId)

    CfUtils.FillImage(self.EngraveImgAttributeIcon, attrVo.icon)
    CfUtils.FillText(self.EngraveAttrNameTxt, attrAdditionVo.attrAdditionName)
    local equipDojo = dojo
    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    local mainEquipAttrVo = cardConfMgr:GetEquipAttrVoById(equipVo.poolMain)
    local attrAddVo = cardConfMgr:GetBasicAttrAdditionById(mainEquipAttrVo.attrAdditionId)
    local addition = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentEngraveAddiRate))
    local value = equipDojo.mainAttrNum * addition
    CfUtils.FillText(self.EngraveAttrNumTxt, math.floor(value + 0.5))
    CfUtils.SetUISwitchText(self.EngraveAttrNameTxt, isActive and 2 or 1)
    CfUtils.SetUISwitchText(self.EngraveAttrNumTxt, isActive and 2 or 1)
end

