function CardProgressionEquipmentInfoNode:RefreshLockBtn(locked, status, isHideLockBtn)
    local isShow = status ~= Status.Preview and isHideLockBtn ~= true
    KTool.SetActive(self.LockBtn.gameObject, isShow)
    local lockNode = self.AnimRoot.transform:Find('TopGroup/LockNode')
    if isNotNull(lockNode) then
        CfUtils.SetActive(lockNode, isShow)
    end
    if isShow then
        CfUtils.SetUISwitchImage(self.LockBtn, locked == 0 and 1 or 2)
        CfUtils.SetUISwitchImage(self.LockImgBg, locked == 0 and 1 or 2)
    end
end

---刷新装备评分
function CardProgressionEquipmentInfoNode:RefreshEvaluateScore(dojo)
    local score = equipComp:CalculateEvaluateScore(dojo)
    CfUtils.FillText(self.ScoreTxtNumber, score)
    local rankConf = CfUtils.GetCf(AutoIds.IdSetting6124, "EquipmentScoreRankVo", true)
    for _, v in ipairs(checkTable(rankConf)) do
        if score >= checkInt(v.rankScoremin) and score <= checkInt(v.rankScoremax) then
            local rank = v.rank
            local conf = CardProgressionConstants.EquipScoreRankConf[rank]
            if conf then
                local path, colorString = SafeUnpack(conf)
                local color = XLuaUtils.HexToColor(colorString)
                self.ImgScore1.color = color
                self.ImgScore2:LoadSprite(path)
                self.ImgScore2:SetColor(color)
            end
            -- CfUtils.SetUISwitchImage(self.ImgScore1, v.rank)
            -- CfUtils.SetUISwitchImage(self.ImgScore2, v.rank)
            break
        end
    end
end

---RefreshAllAttrNode
---刷新副属性列表
---@param equipDojo EquipDojo
---@param equipVo EquipVo
---@param mainAttrDif integer
function CardProgressionEquipmentInfoNode:RefreshAllAttrNode(equipDojo, equipVo, mainAttrDif)
    -- 刷新主属性
    local mainAttrAdditionId = equipDojo.mainAttrId
    local attrAdditionVo = cardConfMgr:GetBasicAttrAdditionById(mainAttrAdditionId)
    local mainEquipAttrVo = cardConfMgr:GetEquipAttrVoById(equipVo.poolMain)
    local attrAddVo = cardConfMgr:GetBasicAttrAdditionById(mainEquipAttrVo.attrAdditionId)
    local attrVo = cardConfMgr:GetBasicAttr(attrAddVo.attrId)
    CfUtils.FillImage(self.MainImgAttributeIcon, attrVo.icon)
    CfUtils.FillText(self.TxtMainAttr, attrAdditionVo.attrAdditionName)
    CfUtils.FillText(self.TxtMainAttrNum, attribute_format(attrAddVo.isConversion, equipDojo.mainAttrInit))

    if checkInt(mainEquipAttrVo.isRandom) == 0 then
        CfUtils.FillText(self.TxtMainAttrNum, string.format('<color=#484848>%s</color>', attribute_format(attrAddVo.isConversion, equipDojo.mainAttrInit)))
        CfUtils.SetActive(self.BtnExplain, false)
    else
        CfUtils.FillText(self.TxtMainAttrNum, attribute_format(attrAddVo.isConversion, equipDojo.mainAttrInit))
        CfUtils.SetUISwitchText(self.TxtMainAttrNum, EquipUtils.GetEquipmentMainAttrQuality(equipDojo))
        CfUtils.SetActive(self.BtnExplain, true)
    end
    
    if checkInt(equipDojo.level) == 0 and checkInt(equipDojo.star) == 0 then
        CfUtils.SetActive(self.TxtMainAttrNumAdd, false)
    else
        CfUtils.SetActive(self.TxtMainAttrNumAdd, true)
        local changeValue = tonumber(equipDojo.mainAttrNum) - tonumber(equipDojo.mainAttrInit)
        CfUtils.FillText(self.TxtMainAttrNumAdd, "+" .. attribute_format(attrAddVo.isConversion, changeValue))
    end
    
    -- 刷新副属性
    local subAttrMaxCount = EquipUtils.GetEquipmentSubAttrMaxCountByDojo(equipDojo)
    for i = 1, CardProgressionConstants.EquipmentSubAttrLimit do
        local go = self.subAttrNodes[i]
        if go == nil then
            if i == 1 then
                go = self.SubAttrNode
            else
                go = self.AttrNodes.gameObject:AddChild(self.SubAttrNode.gameObject)
            end
            self.subAttrNodes[i] = go
        end
        local isShow = i <= subAttrMaxCount
        KTool.SetActive(go.gameObject, isShow)
        if isShow then
            local unlockAttrStar = checkInt(equipDojo.star) >= i and nil or i
            self:RefreshAttrNode(go, equipDojo, i, unlockAttrStar)
        end
    end

    --self:RefreshAttrDifference(mainAttrDif)
end

---刷新主属性差异
function CardProgressionEquipmentInfoNode:RefreshAttrDifference(mainAttrDif)
    if not mainAttrDif or mainAttrDif == 0 then
        CfUtils.SetActive(self.TxtNumUpDown, false)
        return 
    end

    CfUtils.SetActive(self.TxtNumUpDown, true)
    CfUtils.FillText(self.TxtNumUpDown, mainAttrDif)
    local isIncrease = mainAttrDif > 0
    CfUtils.SetUISwitchText(self.TxtNumUpDown, isIncrease and 1 or 2)
    local imgArrow = self.TxtNumUpDown:Find('ImgArrow')
    CfUtils.SetUISwitchImage(imgArrow, isIncrease and 1 or 2)
end

