---OnGetItemByIndex
---随从列表刷新回调
---@param listView SuperScrollView.LoopListView2 列表对象
---@param index number c#中的index
---@return SuperScrollView.LoopListViewItem2
function CardProgressionEquipmentInfoNode:OnGetItemByIndex(listView, index)
    local position = index + 1
    if position < 1 then
        return nil
    end

    -- 创建cell
    local cell = listView:NewListViewItem(PrefabNameDescNode)
    if not KTool.IsNull(cell) then
        --- cell绑定的脚本
        local cellViewMB = GetLuaBehaviour(cell.gameObject, PrefabMBDescNodePath)
        if not KTool.IsNull(cellViewMB) then
            ---@type UICultivateEquipIntroductionDescNodeMB
            local mbEnv = cellViewMB.Env
            if not cell.IsInitHandlerCalled then
                cell.IsInitHandlerCalled = true
            end

            local suitEffectData = self.suitEffectList[position]
            if mbEnv then
                mbEnv:RefreshUI(suitEffectData, position, self.lastActiveIndex, self.params.iShowCanActive)
            end

        end
    end

    return cell
end

function CardProgressionEquipmentInfoNode:RefreshBottomNode(status, dojo)
    local isPreview = status == Status.Preview
    KTool.SetActive(self.BottomNode.gameObject, not isPreview)
    if isPreview then return end
    local conf = StatusConf[status]
    local isShowBtn = conf ~= nil and next(conf) ~= nil
    KTool.SetActive(self.BottomButtons.gameObject, isShowBtn)
    local btnClearUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id116)
    KTool.SetActive(self.BtnClear, isShowBtn and btnClearUnlock)
    KTool.SetActive(self.FontStyleButton.gameObject, status == Status.Installed)
    if isShowBtn then
        local left          = conf.left
        local isShowLeftBtn = left ~= nil
        KTool.SetActive(self.LeftButton.gameObject, isShowLeftBtn)

        if isShowLeftBtn then
            local text, styleId = SafeUnpack(left)

            --- 只有装备可能会显示 eft btn
            local level = checkNumber(dojo.level)
            local star = checkNumber(dojo.star)
            local maxLevel = EquipUtils.GetEquipmentLvMaxByDojo(dojo)
            local isMaxLevel = level == maxLevel
            
            local maxStar = EquipUtils.GetEquipmentStarMaxByDojo(dojo)
            local isMaxStar = checkNumber(dojo.star) == maxStar
            
            local leftStatus
            local isEngraved = checkInt(dojo.bindPlayerCardId) > 0
            if  EquipUtils.IsCanLadderRise(dojo) then
                leftStatus = LeftBtnStatus.LadderRise
                text, styleId = localize("升阶"), FontStyleB25
            elseif EquipUtils.IsCanLadderRiseUpgrade(dojo) then
                leftStatus = LeftBtnStatus.LadderRiseUpgrade
                text, styleId = localize("强化"), FontStyleB25
            elseif isEngraved then
                leftStatus = LeftBtnStatus.Engraved
                text, styleId = localize("已刻印"), "B21"
            elseif isMaxLevel and isMaxStar then
                if GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id115) and EquipUtils.CanEngrave(dojo) then
                    leftStatus = LeftBtnStatus.CanEngrave
                    text, styleId = localize("刻印"), "B25"
                else
                    text, styleId = localize("已满级"), "B21"
                end
            else
                leftStatus = LeftBtnStatus.Cultivate
                text, styleId = SafeUnpack(left)
            end
            if leftStatus ~= self._leftStatus then
                self.BottomNode:Play("CultivateOverseaEquipDetailsGroup_BottonChange")
                self._leftStatus = leftStatus
                
            end

            self.LeftButton:ResetFontStyle(styleId, text)
            self.isMaxLevel = isMaxLevel and isMaxStar
            self.isEngraved = isEngraved
            --KTool.SetActive(self.LeftButton.gameObject, not isMaxLevel)
            --KTool.SetActive(self.TxtMax.gameObject, isMaxLevel)
        else
            self.isMaxLevel = false
            --KTool.SetActive(self.TxtMax.gameObject, false)
            --KTool.SetActive(self.LeftButton.gameObject, false)
        end

        local right          = conf.right
        local isShowRightBtn = right ~= nil
        KTool.SetActive(self.RightButton.gameObject, isShowRightBtn)
        if isShowRightBtn then
            local text, styleId = SafeUnpack(right)
            self.RightButton:ResetFontStyle(styleId, text)
        end
    end

end

---刷新套装描述
function CardProgressionEquipmentInfoNode:RefreshSuitDesc(dojo)
    local equipVo = cardConfMgr:GetEquipVoById(dojo.equipmentId)
    local equipFilterVo = CfUtils.GetCfVo(AutoIds.IdSetting102, "EquipFilterVo", equipVo.suitId)
    CfUtils.FillText(self.DescText, equipFilterVo.desc)

    if checkInt(self.playerCardId) == 0 then
        CfUtils.SetActive(self.ImgTypeIcon, false)
        CfUtils.SetActive(self.TextDesc, false)
        CfUtils.SetUISwitchText(self.DescText, 1)
        return
    else
        CfUtils.SetActive(self.ImgTypeIcon, true)
        CfUtils.SetActive(self.TextDesc, true)
    end
    
    -- 计算当前套装装备数量
    local cardDojo = cardComp:GetCardById(self.playerCardId)
    local num = 0
    for i = 1, CardProgressionConstants.EquipmentNum do
        if i == checkInt(equipVo.part) then
            num = num + 1
        else
            local playerEquipmentId = cardDojo[string.format('equipment%d', i)]
            if checkInt(playerEquipmentId) > 0 then
                local equipDojo = equipComp:GetEquipById(playerEquipmentId)
                local curEquipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
                if curEquipVo.suitId == equipVo.suitId then
                    num = num + 1
                end
            end
        end
    end
    local isActive = num >= checkInt(equipFilterVo.suitNum)
    CfUtils.SetUISwitchImage(self.ImgTypeIcon, isActive and 2 or 1)
    CfUtils.FillImage(self.ImgTypeIcon, equipFilterVo.icon)
    CfUtils.FillText(self.TextDesc, string.format('%s(%d/%d)', equipFilterVo.name, num, equipFilterVo.suitNum))
    CfUtils.SetUISwitchText(self.TextDesc, isActive and 2 or 1)
    CfUtils.SetUISwitchText(self.DescText, isActive and 2 or 1)
end

---刷新洗练节点
function CardProgressionEquipmentInfoNode:RefreshRecastBtn(dojo)
    local isUnlock = checkInt(dojo.star) > 0
    CfUtils.SetActive(self.BtnClearLock, not isUnlock)
