---@param dojo EquipDojo
function CardProgressionEquipmentInfoNode:RefreshLadderRiseNode(dojo)
    ---@type CardProgressionEquipmentLadderRiseNode
    local mbEnv = CfUtils.GetLuaScr(self.LadderRiseNode, LadderRiseNode)
