function CardProgressionEquipmentInfoNode:OnClickLockBtnAction()
    local params, equipType = self.params, self.equipType
    local isEquip     = equipType == EquipType.Equip
    local dojo        = params.dojo
    local status      = checkNumber(dojo.locked) == 0 and 1 or 0
    local requestData = {status = status}
    if isEquip then
        requestData.playerEquipmentId = dojo.id
    else
        requestData.playerEquipmentCoreId = dojo.id
    end
    local id = dojo.id
    
    GameUtils.Request(Interfaces.OverseaEquipmentLock, requestData, function(request, response)
        if checkInt(response.errCode) == 0 then
            if isEquip then
                equipComp:SetLockStateById(id, status)
            else
                equipComp:SetLockStateByCoreId(id, status)
            end

            self:RefreshLockBtn(checkNumber(dojo.locked), params.status)
            if checkNumber(dojo.locked) > 0 then
                GameUtils.Toast(localize("锁定成功"))
            end

            Events.Broadcast(Constants.EventNames.UICultivateEquipChangeLockStateComplete, id, checkNumber(dojo.locked), equipType)
        end
    end)
end

function CardProgressionEquipmentInfoNode:OnClickLeftButtonAction()
    if self.isEngraved then
        GameUtils.Toast(localize("已刻印"))
        return
    end

    local dojo = self._equipDojo
        ---不能升阶
    if  not EquipUtils.IsCanLadderRise(dojo) and
        ---不能强化
        not EquipUtils.IsCanLadderRiseUpgrade(dojo) and
        ---不能刻印
        (not (GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id115) and EquipUtils.CanEngrave(dojo))) and 
        ---是最大等级
        self.isMaxLevel then
            GameUtils.Toast(localize("已满级"))
            return
    end
    
    local params, equipType = self.params, self.equipType
    Events.Broadcast(Constants.EventNames.UICultivateEquipOperateEquipOrCore, params, equipType, 1)
end

function CardProgressionEquipmentInfoNode:OnClickRightButtonAction()
    local params, equipType = self.params, self.equipType
    Events.Broadcast(Constants.EventNames.UICultivateEquipOperateEquipOrCore, params, equipType, 2)
end

function CardProgressionEquipmentInfoNode:OnClickClearButtonAction()
    if checkInt(self._equipDojo.star) == 0 then 
        GameUtils.Toast(localize("升星后解锁"))
        return 
    end
    local params, equipType = self.params, self.equipType
    Events.Broadcast(Constants.EventNames.UICultivateEquipOperateEquipOrCore, params, equipType, 3)
end

function CardProgressionEquipmentInfoNode:OnClickBtnExplainAction()
    CfUtils.SetActive(self.TipsBoardSkillDesc, true)
    local equipVo = cardConfMgr:GetEquipVoById(self._equipDojo.equipmentId)
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._equipDojo.equipmentId)
    local mainEquipAttrVo = cardConfMgr:GetEquipAttrVoById(equipVo.poolMain)
    local attrAddVo = cardConfMgr:GetBasicAttrAdditionById(mainEquipAttrVo.attrAdditionId)
    local attrNum = mainEquipAttrVo.attrNum[tostring(goodsVo.quality)]
    
    -- 更新坐标
    local defineTipsX = 558
    local defineBtnX = -20
    local offsetX = defineBtnX - self.BtnExplain.localPosition.x
    self.TipsBoardSkillDesc.localPosition = Vector2.New(defineTipsX - offsetX, self.TipsBoardSkillDesc.localPosition.y)
    
    CfUtils.FillText(self.TipsTextTitle, localize("主属性说明"))
    CfUtils.FillText(self.TipsTextDesc1, localize("该装备的基础属性随机出现，范围是<color=#FF1BAF>(_num1_~_num2_)</color>", {_num1_ = attribute_format(attrAddVo.isConversion, attrNum.baseMin), _num2_ = attribute_format(attrAddVo.isConversion, attrNum.baseMax)}))
    CfUtils.FillText(self.TipsTextDesc2, localize("这个范围分为6个品质，灰绿蓝紫橙红。这个品质越高，每次升级时，带来的加成越高"))
end

function CardProgressionEquipmentInfoNode:OnClickScoreBtnCheckAction()
    self._isShowScorePanel = not checkBool(self._isShowScorePanel)
    if checkInt(self.params.status) == Status.CultivateAndReplace then
        Events.Broadcast(Constants.EventNames.CardProgressEquipInfoSwitchScorePanelState, self._isShowScorePanel)
    end
    
    self:SwitchScorePanelState(self._isShowScorePanel)
end

function CardProgressionEquipmentInfoNode:SwitchScorePanelState(isShow)
    if isShow then
        CfUtils.SetActive(self.EvaluateScoreDetail, true)
        CfUtils.PlayAnimation(self.EvaluateScoreDetail, "CultivateOverseaEquipDetailsNode_EvaluateScoreDetail_go",true)
        local scr = CfUtils.GetLuaScr(self.EvaluateScoreDetail, "Game.CardProgression.Equip.CardProgressionEquipmentScoreDetailNode")
        if scr then
            scr:RefreshUI(self._equipDojo)
        end
    else
        CfUtils.PlayAnimation(self.EvaluateScoreDetail, "CultivateOverseaEquipDetailsNode_EvaluateScoreDetail_back",true)
    end
end

function CardProgressionEquipmentInfoNode:PanelCloseEventHandler()
    if self._isShowScorePanel then
        self._isShowScorePanel = false
        CfUtils.PlayAnimation(self.EvaluateScoreDetail, "CultivateOverseaEquipDetailsNode_EvaluateScoreDetail_back",true)
    end
end
--endregion private

return CardProgressionEquipmentInfoNode